Q: How to detect Light\Dark mode change in iOS 13? A: <p>The accepted answer works fine, but as pointed out by <a href="https://stackoverflow.com/questions/58016866/how-to-detect-light-dark-mode-change-in-ios-13#comment113929326_58017164">@Eugenio</a>, the app momentarily changes <code>colorScheme</code> and reverts when going to the <code>background</code>. If you need to make sure to detect only <strong>real</strong> <code>colorScheme</code> changes the work around is to combine it with <code>scenePhase</code>.</p>
<h2>Example on SwiftUI</h2>
<pre class="lang-swift prettyprint-override"><code>struct ContentView: View {
    @Environment(\.colorScheme) private var colorScheme
    @Environment(\.scenePhase) private var scenePhase

    var body: some View {
        VStack {
            /// content
        }
        .onChange(of: colorScheme) {
            switch scenePhase {
            case .active:
                /// Color scheme changed while active
                break
            case .inactive:
                /// Color scheme changed while app was in background
                break
            case .background:
                /// Ignore as the app went to the background
                /// but `colorScheme` is the same
                break
            @unknown default:
                break
            }
        }
    }
}
</code></pre>

Q: How to make a report module in laravel? A: <p>So the first thing to do is<br />
1. Install Only the PDF Package</p>
<p><code>composer require barryvdh/laravel-dompdf</code></p>
<p>2. In your Controller</p>
<pre><code>namespace App\Http\Controllers;

use App\Models\Product;
use Illuminate\Http\Request;
use Barryvdh\DomPDF\Facade\Pdf;

class ReportController extends Controller
{
    public function index(Request $request)
    {
        $query = Fruit::query();

        if ($request-&gt;filled('category')) {
            $query-&gt;where('category', $request-&gt;category);
        }

        if ($request-&gt;filled('availability')) {
            $query-&gt;where('availability', $request-&gt;availability);
        }

        $product = $query-&gt;get();
        $categories     = ['citrus', 'berry', 'stone fruit', 'tropical', 'pome'];
        $availabilities = ['available', 'out of stock'];

        return view('reports.index', compact('fruits', 'categories', 'availabilities'));
    }

    public function exportPDF(Request $request)
    {
        $query = Fruit::query();

        if ($request-&gt;filled('category')) {
            $query-&gt;where('category', $request-&gt;category);
        }

        if ($request-&gt;filled('availability')) {
            $query-&gt;where('availability', $request-&gt;availability);
        }

        $fruits = $query-&gt;get();
        $pdf    = Pdf::loadView('reports.pdf', compact('fruits'));

        return $pdf-&gt;download('fruits-report.pdf');
    }
}
</code></pre>
<p>3. In your Route</p>
<pre><code>// routes/web.php

use App\Http\Controllers\ReportController;

Route::get('/reports',            [ReportController::class, 'index'])-&gt;name('reports.index');
Route::get('/reports/export-pdf', [ReportController::class, 'exportPDF'])-&gt;name('reports.pdf');
</code></pre>
<p>4. Then you need to make a blade view for you report index</p>
<pre><code>&lt;form method=&quot;GET&quot; action=&quot;{{ route('reports.index') }}&quot;&gt;

    {{-- Filter by Category --}}
    &lt;select name=&quot;category&quot;&gt;
        &lt;option value=&quot;&quot;&gt;All Categories&lt;/option&gt;
        @foreach ($categories as $category)
            &lt;option value=&quot;{{ $category }}&quot; {{ request('category') == $category ? 'selected' : '' }}&gt;
                {{ ucwords($category) }}
            &lt;/option&gt;
        @endforeach
    &lt;/select&gt;

    {{-- Filter by Availability --}}
    &lt;select name=&quot;availability&quot;&gt;
        &lt;option value=&quot;&quot;&gt;All Availability&lt;/option&gt;
        @foreach ($availabilities as $availability)
            &lt;option value=&quot;{{ $availability }}&quot; {{ request('availability') == $availability ? 'selected' : '' }}&gt;
                {{ ucwords($availability) }}
            &lt;/option&gt;
        @endforeach
    &lt;/select&gt;

    &lt;button type=&quot;submit&quot;&gt;Filter&lt;/button&gt;

    {{-- PDF Export Button --}}
    &lt;a href=&quot;{{ route('reports.pdf', request()-&gt;query()) }}&quot;&gt;Export PDF&lt;/a&gt;

&lt;/form&gt;

{{-- Report Table --}}
&lt;table&gt;
    &lt;thead&gt;
        &lt;tr&gt;
            &lt;th&gt;Fruit Name&lt;/th&gt;
            &lt;th&gt;Category&lt;/th&gt;
            &lt;th&gt;Price per KG&lt;/th&gt;
            &lt;th&gt;Stock&lt;/th&gt;
            &lt;th&gt;Availability&lt;/th&gt;
        &lt;/tr&gt;
    &lt;/thead&gt;
    &lt;tbody&gt;
        @forelse ($products as $product)
            &lt;tr&gt;
                &lt;td&gt;{{ $product-&gt;fruit_name }}&lt;/td&gt;
                &lt;td&gt;{{ ucwords($product-&gt;category) }}&lt;/td&gt;
                &lt;td&gt;{{ $product-&gt;price_per_kg }}&lt;/td&gt;
                &lt;td&gt;{{ $product-&gt;stock }}&lt;/td&gt;
                &lt;td&gt;{{ ucwords($product-&gt;availability) }}&lt;/td&gt;
            &lt;/tr&gt;
        @empty
            &lt;tr&gt;
                &lt;td colspan=&quot;5&quot;&gt;No product found.&lt;/td&gt;
            &lt;/tr&gt;
        @endforelse
    &lt;/tbody&gt;
&lt;/table&gt;
</code></pre>
